create or alter procedure api.DeleteGroups
	@executionId int
as
begin
	set nocount on;
	declare @userId int,
			@date datetime,
			@object varchar(50) = 'Group',
			@assetTypeId int,
			@transactionCompleted bit = 0;

	select @assetTypeId = ID from AssetType where Object = 'GroupType';

	select	@userId = ResourceID,
			@date = StartedOn
	from	api.Execution 
	where	ID = @executionId;

	drop table if exists #Items;
	create table #Items (
		ItemNumber int, 
		[Uid] uniqueidentifier, 
		IsSuccess bit, 
		ObjectID int, AssetID bigint, 
		[Message] nvarchar(max)
	);

	-- Get data from JSON columns in api.ExecutionItem
	insert into #Items (ItemNumber, Uid)
		select	ItemNumber,
				JSON_VALUE(Properties, '$.Uid')
		from	api.ExecutionItem
		where	ExecutionId = @executionId;

	-- Validate incoming data.
	update	t
	set		t.IsSuccess = 0,
			t.Message = 'Group does not exist.'
	from	#Items  t
			left join [Group] s on s.Uid = t.Uid and t.Uid is not null
	where	s.ID is null;

	-- Populate internal IDs for group based on the incoming Uid.
	update	t
	set		t.ObjectID = s.ID
	from	#Items  t
			inner join [Group] s on s.Uid = t.Uid and t.Uid is not null and IsSuccess is null;

	update	t
	set		t.AssetID = s.ID
	from	#Items  t
			inner join [Asset] s on s.Object = @object and s.ObjectID = t.ObjectID and IsSuccess is null;

	begin try
		begin transaction;


		insert into reporting.Global_Audit 
			(
			Object, ObjectID, ObjectName, 
			ResourceID, Date, Action, ActionObject, ActionObjectID, ActionObjectTypeName, ActionObjectName, ActionDescription, 
			[Version]
			)
			select	distinct 
					@object, 
					g.ID, 
					G.Name, 
					@userId, 
					@date, 
					'Removed', 
					@object, 
					g.ID, 
					@object, 
					G.Name, 
					'',
					mv.[Version]
			from	[Group] g 
					cross apply (select coalesce(max([Version]),0)+1 as [Version] from reporting.Global_Audit where Object = @object and ObjectID = g.ID) mv
			where	g.ID in (select ObjectID from #Items where IsSuccess is null);

		delete	t
		from	ResourceGroup t 
				inner join #Items s on s.ObjectID = t.GroupID and s.IsSuccess is null;

		delete	t
		from	Field t 
				inner join #Items s on t.ObjectType = @object and s.ObjectID = t.ObjectID and s.IsSuccess is null;

		delete	t
		from	AssetDisplayValue t 
				inner join #Items s on s.AssetID = t.AssetID and s.IsSuccess is null;

		delete	t
		from	AssetPath t 
				inner join #Items s on s.AssetID = t.ID and s.IsSuccess is null;

		delete	t
		from	Asset t 
				inner join #Items s on s.AssetID = t.ID and s.IsSuccess is null;

		delete	t
		from	[Group] t 
				inner join #Items s on s.ObjectID = t.ID and s.IsSuccess is null;

		commit transaction;
		set @transactionCompleted = 1;
	end try
	begin catch
		rollback transaction;
	end catch

	if @transactionCompleted = 1
	begin
		-- Updated the messaging.
		update	#Items
		set		Message = 'Deleted successfully',
				IsSuccess = 1
		where	IsSuccess is null

		-- Update api.ExecutionItem
		update	t
		set		t.Success = s.IsSuccess,
				t.Message = s.Message
		from	api.ExecutionItem t
				inner join #Items s on s.ItemNumber = t.ItemNumber and t.ExecutionId = @executionId;

		update	t
		set		t.Properties = JSON_MODIFY(t.Properties, '$.id', s.ObjectID)
		from	api.ExecutionItem t
				inner join #Items s on s.ItemNumber = t.ItemNumber and t.ExecutionId = @executionId and s.ObjectID is not null;

		update	t
		set		t.Properties = JSON_MODIFY(t.Properties, '$.assetId', s.AssetID)
		from	api.ExecutionItem t
				inner join #Items s on s.ItemNumber = t.ItemNumber and t.ExecutionId = @executionId and s.ObjectID is not null;

		exec api.CompleteExecution @executionId, @date, '';
	end
	else
	begin 
		exec api.CompleteExecution @executionId, @date, 'Transaction failed to complete.';
	end

end
